// Bit-exact parity test for the FULL single Mamba-2 layer decode step.
// Compares C++ mamba_layer_forward against vectors generated by the REAL
// NemotronHMamba2Mixer.__call__ (tools/gen_mamba_vectors.py), viewing the raw
// bytes (uint16 for 2-byte dtypes, uint32 for 4-byte) — no tolerance.
// Key intermediates are also checked so a failure localizes to one primitive.
#include "../src/mamba_layer.hpp"

#include "mamba_conv.h"
#include "mamba_kernel.h"

#include <mlx/mlx.h>
#include <mlx/fast.h>

#include <cstdint>
#include <cstdio>
#include <fstream>
#include <optional>
#include <sstream>
#include <string>
#include <utility>
#include <vector>

namespace mx = mlx::core;
using namespace veystrix::engine;

static std::string read_all(const std::string& path) {
  std::ifstream f(path);
  std::ostringstream ss;
  ss << f.rdbuf();
  return ss.str();
}

// Parse a numeric value (int or float) for a quoted JSON key.
static double meta_num(const std::string& txt, const std::string& key) {
  const std::string k = "\"" + key + "\":";
  size_t p = txt.find(k);
  if (p == std::string::npos) {
    std::fprintf(stderr, "meta.json missing key %s\n", key.c_str());
    return 0.0;
  }
  p += k.size();
  while (p < txt.size() && (txt[p] == ' ' || txt[p] == '\t')) ++p;
  size_t q = p;
  while (q < txt.size() && txt[q] != ',' && txt[q] != '}' && txt[q] != '\n') ++q;
  return std::stod(txt.substr(p, q - p));
}

// True bit reinterpretation: uint16 for 2-byte dtypes, uint32 for 4-byte.
static mx::Dtype view_dtype(const mx::array& a) {
  return (a.dtype() == mx::bfloat16 || a.dtype() == mx::float16)
             ? mx::uint16
             : mx::uint32;
}
static bool bit_equal(const mx::array& a, const mx::array& b) {
  if (a.shape() != b.shape() || a.dtype() != b.dtype()) return false;
  mx::array av = mx::view(mx::reshape(a, {-1}), view_dtype(a));
  mx::array bv = mx::view(mx::reshape(b, {-1}), view_dtype(b));
  mx::eval(av, bv);
  if (av.size() != bv.size()) return false;
  if (view_dtype(a) == mx::uint16) {
    const uint16_t* x = av.data<uint16_t>();
    const uint16_t* y = bv.data<uint16_t>();
    for (size_t i = 0; i < av.size(); ++i) if (x[i] != y[i]) return false;
  } else {
    const uint32_t* x = av.data<uint32_t>();
    const uint32_t* y = bv.data<uint32_t>();
    for (size_t i = 0; i < av.size(); ++i) if (x[i] != y[i]) return false;
  }
  return true;
}
static void dump_first_diff(const char* label, const mx::array& a,
                            const mx::array& b) {
  if (a.shape() != b.shape() || a.dtype() != b.dtype()) {
    std::fprintf(stderr, "  %s shape/dtype differs\n", label);
    return;
  }
  mx::array av = mx::view(mx::reshape(a, {-1}), view_dtype(a));
  mx::array bv = mx::view(mx::reshape(b, {-1}), view_dtype(b));
  mx::eval(av, bv);
  if (view_dtype(a) == mx::uint16) {
    const uint16_t* x = av.data<uint16_t>();
    const uint16_t* y = bv.data<uint16_t>();
    for (size_t i = 0; i < av.size(); ++i)
      if (x[i] != y[i]) {
        std::fprintf(stderr, "  %s first diff at %zu: got 0x%04x expected 0x%04x\n",
                     label, i, x[i], y[i]);
        return;
      }
  } else {
    const uint32_t* x = av.data<uint32_t>();
    const uint32_t* y = bv.data<uint32_t>();
    for (size_t i = 0; i < av.size(); ++i)
      if (x[i] != y[i]) {
        std::fprintf(stderr, "  %s first diff at %zu: got 0x%08x expected 0x%08x\n",
                     label, i, x[i], y[i]);
        return;
      }
  }
}

int main(int argc, char** argv) {
  if (argc < 2) {
    std::fprintf(stderr, "usage: %s <vectordir>\n", argv[0]);
    return 2;
  }
  const std::string dir = argv[1];
  auto load = [&](const char* n) { return mx::load(dir + "/" + n + ".npy"); };

  mx::array x = load("x");
  mx::array w_in = load("w_in"), conv_w = load("conv_w"), conv_b = load("conv_b");
  mx::array A_log = load("A_log"), dt_bias = load("dt_bias"), D = load("D");
  mx::array norm_w = load("norm_w"), w_out = load("w_out");
  mx::array conv_state = load("conv_state"), ssm_state = load("ssm_state");

  mx::array e_out = load("expected_output");
  mx::array e_conv = load("expected_conv_state");
  mx::array e_ssm = load("expected_ssm_state");

  std::string meta_txt = read_all(dir + "/meta.json");
  const int hidden = (int)meta_num(meta_txt, "hidden");
  const int H = (int)meta_num(meta_txt, "H");
  const int Dh = (int)meta_num(meta_txt, "Dh");
  const int G = (int)meta_num(meta_txt, "G");
  const int Ds = (int)meta_num(meta_txt, "Ds");
  const int K = (int)meta_num(meta_txt, "K");
  const int I = (int)meta_num(meta_txt, "inter");
  const int conv_dim = (int)meta_num(meta_txt, "conv_dim");
  const float eps = (float)meta_num(meta_txt, "eps");
  const float tmin = (float)meta_num(meta_txt, "tmin");
  const float tmax = (float)meta_num(meta_txt, "tmax");

  MambaWeights weights(w_in, conv_w, conv_b, A_log, dt_bias, D, norm_w, w_out);
  MambaCacheState cache(conv_state, ssm_state);
  MambaConfig cfg{hidden, H, Dh, G, Ds, K, I, conv_dim, eps, tmin, tmax};

  MambaLayerOutput got = mamba_layer_forward(x, weights, cache, cfg);
  mx::eval(got.output, got.conv_state, got.ssm_state);

  bool ok = true;
  auto check = [&](const char* label, const mx::array& a, const mx::array& b) {
    if (!bit_equal(a, b)) {
      std::fprintf(stderr, "FAIL: %s differs\n", label);
      dump_first_diff(label, a, b);
      ok = false;
    }
  };
  check("output", got.output, e_out);
  check("conv_state", got.conv_state, e_conv);
  check("ssm_state", got.ssm_state, e_ssm);

  // --- Intermediate isolation: recompute the real op chain and compare each
  // saved tensor (same as gen_mamba_vectors.py). ---
  const int B = x.shape(0);
  mx::array projected = linear(x, weights.in_proj);
  check("i_projected", projected, load("i_projected"));

  mx::array gate = mx::slice(projected, mx::Shape{0, 0, 0}, mx::Shape{B, 1, I});
  mx::array conv_input = mx::slice(projected, mx::Shape{0, 0, I},
                                   mx::Shape{B, 1, I + conv_dim});
  mx::array dt_raw = mx::slice(projected, mx::Shape{0, 0, I + conv_dim},
                               mx::Shape{B, 1, I + conv_dim + H});
  check("i_gate", gate, load("i_gate"));
  check("i_conv_input", conv_input, load("i_conv_input"));
  check("i_dt_raw", dt_raw, load("i_dt_raw"));

  MambaConvPrep prep = mamba_conv_prep(conv_state, conv_input, K);
  check("i_padded", prep.padded, load("i_padded"));

  mx::array conv_out = mamba_causal_conv_decode_silu(
      prep.padded, weights.conv1d_weight, weights.conv1d_bias);
  check("i_conv_out", conv_out, load("i_conv_out"));

  mx::array hidden_ssm = mx::slice(conv_out, mx::Shape{0, 0, 0},
                                   mx::Shape{B, 1, I});
  mx::array Bv = mx::slice(conv_out, mx::Shape{0, 0, I},
                           mx::Shape{B, 1, I + G * Ds});
  mx::array Cv = mx::slice(conv_out, mx::Shape{0, 0, I + G * Ds},
                           mx::Shape{B, 1, I + 2 * G * Ds});
  hidden_ssm = mx::reshape(hidden_ssm, mx::Shape{B, 1, H, Dh});
  Bv = mx::reshape(Bv, mx::Shape{B, 1, G, Ds});
  Cv = mx::reshape(Cv, mx::Shape{B, 1, G, Ds});
  check("i_hidden_ssm", hidden_ssm, load("i_hidden_ssm"));
  check("i_B", Bv, load("i_B"));
  check("i_C", Cv, load("i_C"));

  mx::array got_dt_post = compute_dt(dt_raw, weights.dt_bias, tmin, tmax);
  check("i_dt_post", got_dt_post, load("i_dt_post"));

  mx::array D_h = mx::astype(weights.D, x.dtype());
  SSMStepOutput step = mamba_ssm_step_kernel(
      hidden_ssm, weights.A_log, Bv, Cv, D_h, dt_raw, weights.dt_bias,
      ssm_state, tmin, tmax);
  check("i_y", step.y, load("i_y"));
  check("i_state", step.state, load("i_state"));

  mx::array y = mx::reshape(step.y, mx::Shape{B, 1, I});
  mx::array normed = swiglu(gate, y);
  normed = mx::reshape(normed, mx::Shape{B, 1, G, I / G});
  normed = mx::fast::rms_norm(normed, std::nullopt, eps);
  normed = mx::reshape(normed, mx::Shape{B, 1, I});
  normed = weights.norm_weight * normed;
  check("i_normed", normed, load("i_normed"));

  if (!ok) return 1;
  std::printf("test_mamba_layer OK (bit-exact output + conv_state + ssm_state + intermediates)\n");
  return 0;
}
